// ========================================================================
// Step 1: Run subscription detection
// ========================================================================
// This calls the detection logic inline (same algorithm as
// scripts/detect-subscriptions.js) via Plaid transactions already synced
// in Neon.  We do the detection first, then query the results.
//
// Since n8n Code nodes can't import external modules on Community Edition,
// we call the detection script via the Execute Command node instead.
// This Code node just returns a passthrough signal.
// ========================================================================
return [{ json: { trigger: 'digest' } }];

// ========================================================================
// Build the weekly digest email body
// ========================================================================
const subs = $input.all().map(i => i.json);

if (subs.length === 0) {
  return [{ json: { subject: 'Subscription Digest — No Active Subscriptions', body: '<p>No recurring subscriptions detected yet. Transactions may still be syncing.</p>' } }];
}

// Calculate estimated monthly cost
let monthlyTotal = 0;
for (const s of subs) {
  const amt = parseFloat(s.amount);
  if (s.cadence_days <= 35) monthlyTotal += amt;          // ~monthly
  else if (s.cadence_days <= 65) monthlyTotal += amt / 2; // ~bimonthly
  else if (s.cadence_days <= 95) monthlyTotal += amt / 3; // ~quarterly
  else monthlyTotal += amt / (s.cadence_days / 30);       // other
}

const newSubs = subs.filter(s => s.is_new);
const changedSubs = subs.filter(s => s.amount_changed);

// Format currency
const fmt = (n) => '$' + parseFloat(n).toFixed(2);
const fmtDate = (d) => d ? new Date(d).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : '—';

// Build HTML
let html = `<div style="font-family: system-ui, sans-serif; max-width: 600px;">`;
html += `<h2>Weekly Subscription Digest</h2>`;
html += `<p style="font-size: 18px;">Estimated monthly cost: <strong>${fmt(monthlyTotal)}</strong></p>`;

// New subscriptions callout
if (newSubs.length > 0) {
  html += `<div style="background: #e8f5e9; padding: 12px; border-radius: 6px; margin: 16px 0;">`;
  html += `<strong>🆕 New this week:</strong><ul>`;
  for (const s of newSubs) {
    html += `<li>${s.display_name} — ${fmt(s.amount)} every ${s.cadence_days} days</li>`;
  }
  html += `</ul></div>`;
}

// Amount changes callout
if (changedSubs.length > 0) {
  html += `<div style="background: #fff3e0; padding: 12px; border-radius: 6px; margin: 16px 0;">`;
  html += `<strong>💰 Price changes:</strong><ul>`;
  for (const s of changedSubs) {
    const delta = parseFloat(s.amount) - parseFloat(s.prior_amount);
    const arrow = delta > 0 ? '↑' : '↓';
    html += `<li>${s.display_name}: ${fmt(s.prior_amount)} → ${fmt(s.amount)} (${arrow}${fmt(Math.abs(delta))})</li>`;
  }
  html += `</ul></div>`;
}

// Full table
html += `<table style="width: 100%; border-collapse: collapse; margin-top: 16px;">`;
html += `<tr style="background: #f5f5f5;"><th style="text-align: left; padding: 8px;">Subscription</th><th style="padding: 8px;">Amount</th><th style="padding: 8px;">Cycle</th><th style="padding: 8px;">Next Charge</th></tr>`;
for (const s of subs) {
  const cadenceLabel = s.cadence_days <= 35 ? 'Monthly' : s.cadence_days <= 65 ? 'Bi-monthly' : 'Quarterly';
  html += `<tr style="border-bottom: 1px solid #eee;">`;
  html += `<td style="padding: 8px;">${s.display_name}</td>`;
  html += `<td style="padding: 8px; text-align: center;">${fmt(s.amount)}</td>`;
  html += `<td style="padding: 8px; text-align: center;">${cadenceLabel}</td>`;
  html += `<td style="padding: 8px; text-align: center;">${fmtDate(s.next_expected)}</td>`;
  html += `</tr>`;
}
html += `</table>`;
html += `<p style="color: #888; font-size: 12px; margin-top: 24px;">Generated by your personal subscription tracker. ${subs.length} active subscription(s) tracked.</p>`;
html += `</div>`;

// Reset is_new and amount_changed flags after digest
// (We output SQL to run in the next node)
const resetSql = `UPDATE detected_subscriptions SET is_new = false, amount_changed = false WHERE is_active = true;`;

return [{ json: {
  subject: `Subscription Digest — ${subs.length} active, ${fmt(monthlyTotal)}/mo`,
  body: html,
  resetSql,
  subCount: subs.length,
  monthlyTotal: monthlyTotal.toFixed(2),
} }];
